def run(_context):
    import json
    import adsk.cam
    import adsk.core

    cam = mb.get_cam()
    setup = None
    for s in cam.setups:
        if s.name == "Setup1":
            setup = s
            break

    if not setup:
        print("Setup1 not found")
        return

    for op in setup.operations:
        if op.name == "Spot Drill":
            print(f"Operation: {op.name}")
            print(f"  Strategy: {op.strategy}")
            print(f"  IsValid: {op.isValid}")
            print(f"  HasToolpath: {op.hasToolpath}")

            # Check if there's an error
            try:
                error = op.error
                if error:
                    print(f"  Error: {error.message}")
            except:
                pass

            # Check parameters
            params = op.parameters
            for p in params:
                try:
                    if p.isEnabled:
                        print(f"  Param: {p.name} = {p.expression}")
                except:
                    pass

            # Check geometry
            try:
                geom = op.parameters.itemByName("geometry")
                if geom:
                    print(f"  Geometry param: {geom.expression}")
            except:
                pass

            break

